INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q2583734', 'Indonesian invasion of East Timor', 'The Indonesian invasion of East Timor, known in Indonesia as Operation Lotus (Indonesian: Operasi Seroja), began on 7 December 1975 when the Indonesian military (ABRI/TNI) invaded East Timor under the pretext of anti-colonialism and anti-communism to overthrow the Fretilin government that had emerged in 1974. The overthrow of the popular and short-lived Fretilin-led government sparked a violent quarter-century occupation in which approximately 100,000–180,000 soldiers and civilians are estimated to have been killed or starved to death.', 1975, 12, 7, 1979, 3, 26, 'day', '7 December 1975 – 26 March 1979', 61, 'https://en.wikipedia.org/wiki/Indonesian_invasion_of_East_Timor'),
  ('Q2665403', 'Indonesian occupation of East Timor', 'The Indonesian occupation of East Timor began in December 1975 and lasted until October 1999. After centuries of Portuguese colonial rule in East Timor, the 1974 Carnation Revolution in Portugal led to the decolonisation of its former colonies, creating instability in East Timor and leaving its future uncertain.', 1975, 12, 7, 1999, 10, 31, 'day', '7 December 1975 – 31 October 1999', 57, 'https://en.wikipedia.org/wiki/Indonesian_occupation_of_East_Timor'),
  ('Q97381399', 'East Timorese civil war', 'In August 1975, a civil war broke out between two opposing political parties in Portuguese Timor: the conservative Timorese Democratic Union (UDT) and the left-leaning Revolutionary Front for an Independent East Timor (Fretilin). The war took place within the context of decolonisation, as the post–Carnation Revolution Portuguese government sought to give independence to much of the Portuguese Empire.', 1975, 8, 11, 1975, 9, 11, 'day', '11 August 1975 – 11 September 1975', 26, 'https://en.wikipedia.org/wiki/East_Timorese_civil_war'),
  ('Q1786651', 'Kraras Massacre', 'The Kraras massacre was a series of mass killings committed by the Indonesian Army, along with Timorese Hansip members, in August and September 1983 in Kraras, Viqueque Municipality, East Timor. More than 200 civilians, mostly men, died in the killings.', 1983, 8, NULL, 1983, 9, NULL, 'month', 'August 1983 – September 1983', 34, 'https://en.wikipedia.org/wiki/Kraras_massacre'),
  ('Q197916', 'Timor Gap Treaty', 'The Timor Gap Treaty was formally known as the Treaty between Australia and the Republic of Indonesia on the zone of cooperation in an area between the Indonesian province of East Timor and Northern Australia. It was a bilateral treaty between the governments of Australia and Indonesia, which provided for the joint exploitation of petroleum and hydrocarbon resources in a part of the Timor Sea Seabed.', 1989, 12, 11, NULL, NULL, NULL, 'day', '11 December 1989', 37, 'https://en.wikipedia.org/wiki/Timor_Gap_Treaty'),
  ('Q782441', 'Santa Cruz massacre', 'The Santa Cruz massacre (also known as the Dili massacre) was the murder of at least 250 East Timorese pro-independence demonstrators in the Santa Cruz cemetery in the capital, Dili, on 12 November 1991, during the Indonesian occupation of East Timor and is part of the East Timor genocide.', 1991, 11, 12, NULL, NULL, NULL, 'day', '12 November 1991', 51, 'https://en.wikipedia.org/wiki/Santa_Cruz_massacre'),
  ('Q507829', 'Suai Church massacre', 'The Suai Church massacre occurred on 6 September 1999, in Suai, Cova Lima District in southwestern East Timor, two days after the results of the independence referendum were announced.', 1999, 9, 6, NULL, NULL, NULL, 'day', '6 September 1999', 34, 'https://en.wikipedia.org/wiki/Suai_Church_massacre'),
  ('Q97168325', 'East Timor independence', 'Timor is an island in South East Asia. Geologically considered a continental crustal fragment, it lies alongside the Sunda shelf, and is the largest in a cluster of islands between Java and New Guinea.', 2002, 5, 20, NULL, NULL, NULL, 'day', '20 May 2002', 39, 'https://en.wikipedia.org/wiki/Timor-Leste_independence'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic');

